import React, { useState } from 'react';

// ── Seeded RNG — deterministic from book id ───────────────────────
function seededRng(id) {
  let h = 2166136261;
  for (let i = 0; i < id.length; i++) {
    h ^= id.charCodeAt(i);
    h = Math.imul(h, 16777619) >>> 0;
  }
  return () => { h ^= h << 13; h ^= h >> 17; h ^= h << 5; return (h >>> 0) / 0xFFFFFFFF; };
}

// ── Darken / adjust colour ────────────────────────────────────────
function darkenHex(hex, amount = 0.35) {
  const r = parseInt(hex.slice(1,3),16);
  const g = parseInt(hex.slice(3,5),16);
  const b = parseInt(hex.slice(5,7),16);
  const d = v => Math.max(0, Math.round(v * (1 - amount)));
  return `rgb(${d(r)},${d(g)},${d(b)})`;
}
function lightenHex(hex, amount = 0.55) {
  const r = parseInt(hex.slice(1,3),16);
  const g = parseInt(hex.slice(3,5),16);
  const b = parseInt(hex.slice(5,7),16);
  const l = v => Math.min(255, Math.round(v + (255 - v) * amount));
  return `rgb(${l(r)},${l(g)},${l(b)})`;
}
function hexToRgb(hex, a=1) {
  const r=parseInt(hex.slice(1,3),16), g=parseInt(hex.slice(3,5),16), b=parseInt(hex.slice(5,7),16);
  return `rgba(${r},${g},${b},${a})`;
}

// ── Marbled endpaper SVG — Penguin Great Ideas aesthetic ──────────
// Classic paper marbling: veined stone pattern, oil-on-water swirls
function MarbledPattern({ id, color, width = 120, height = 160, small = false }) {
  const rng   = seededRng(id + 'marble');
  const dark  = darkenHex(color, 0.45);
  const mid   = darkenHex(color, 0.20);
  const light = lightenHex(color, 0.35);
  const cream = '#f5f0e4';

  // Generate vein paths — sinuous, organic
  const veins = Array.from({ length: small ? 5 : 9 }, (_, i) => {
    const x0 = rng() * width;
    const y0 = rng() * height;
    const x1 = x0 + (rng() - 0.5) * width * 0.8;
    const y1 = y0 + (rng() - 0.5) * height * 0.8;
    const cx1 = rng() * width;
    const cy1 = rng() * height;
    const cx2 = rng() * width;
    const cy2 = rng() * height;
    const colors = [dark, mid, light, dark, mid];
    return { path: `M${x0},${y0} C${cx1},${cy1} ${cx2},${cy2} ${x1},${y1}`, color: colors[i % colors.length], w: 0.8 + rng() * 1.4 };
  });

  // Swirl blobs — oil drops spreading on water
  const blobs = Array.from({ length: small ? 3 : 6 }, () => ({
    cx: rng() * width, cy: rng() * height,
    rx: 15 + rng() * (small ? 20 : 35),
    ry: 10 + rng() * (small ? 15 : 25),
    rot: rng() * 360,
    color: [dark, mid, light][Math.floor(rng() * 3)],
    opacity: 0.12 + rng() * 0.18,
  }));

  return (
    <svg width={width} height={height} xmlns="http://www.w3.org/2000/svg" style={{ display:'block' }}>
      {/* Base — cream paper */}
      <rect width={width} height={height} fill={cream} />
      {/* Colour wash */}
      <rect width={width} height={height} fill={hexToRgb(color, 0.22)} />
      {/* Gradient sweep — the 'combed' marble effect */}
      <defs>
        <linearGradient id={`mg-${id}`} x1="0" y1="0" x2="1" y2="1">
          <stop offset="0%"   stopColor={dark}  stopOpacity="0.35" />
          <stop offset="40%"  stopColor={mid}   stopOpacity="0.18" />
          <stop offset="70%"  stopColor={light} stopOpacity="0.22" />
          <stop offset="100%" stopColor={dark}  stopOpacity="0.28" />
        </linearGradient>
        <filter id={`blur-${id}`}><feGaussianBlur stdDeviation="2.5"/></filter>
        <filter id={`blur2-${id}`}><feGaussianBlur stdDeviation="1"/></filter>
      </defs>
      <rect width={width} height={height} fill={`url(#mg-${id})`} />
      {/* Blob masses */}
      {blobs.map((b,i) => (
        <ellipse key={i} cx={b.cx} cy={b.cy} rx={b.rx} ry={b.ry}
          transform={`rotate(${b.rot},${b.cx},${b.cy})`}
          fill={b.color} opacity={b.opacity} filter={`url(#blur-${id})`} />
      ))}
      {/* Veins */}
      {veins.map((v,i) => (
        <path key={i} d={v.path} stroke={v.color} strokeWidth={v.w}
          fill="none" opacity={0.65 + i*0.03} filter={`url(#blur2-${id})`} />
      ))}
      {/* Fine veins on top */}
      {veins.slice(0,3).map((v,i) => (
        <path key={'f'+i} d={v.path} stroke={dark} strokeWidth={0.4}
          fill="none" opacity={0.35} />
      ))}
    </svg>
  );
}

// ── Ornamental border — quasi-Victorian, one symbol is wrong ─────
function OrnamentalBorder({ color, width, height }) {
  const gold = color;
  // Corner ornament — looks Victorian but the bottom-right is a circuit node
  return (
    <svg width={width} height={height} style={{ position:'absolute', inset:0, pointerEvents:'none' }} xmlns="http://www.w3.org/2000/svg">
      {/* Outer frame */}
      <rect x="5" y="5" width={width-10} height={height-10} fill="none" stroke={gold} strokeWidth="0.75" opacity="0.6" />
      {/* Inner frame */}
      <rect x="9" y="9" width={width-18} height={height-18} fill="none" stroke={gold} strokeWidth="0.4" opacity="0.4" />
      {/* Corner ornaments — TL, TR, BL all fleur-de-lis style */}
      {/* Top-left */}
      <text x="6" y="16" style={{fontSize:'8px', fill:gold, opacity:0.7, fontFamily:'Georgia, serif'}}>✦</text>
      {/* Top-right */}
      <text x={width-14} y="16" style={{fontSize:'8px', fill:gold, opacity:0.7, fontFamily:'Georgia, serif'}}>✦</text>
      {/* Bottom-left */}
      <text x="6" y={height-5} style={{fontSize:'8px', fill:gold, opacity:0.7, fontFamily:'Georgia, serif'}}>✦</text>
      {/* Bottom-right — slightly wrong. A circuit node. */}
      <g transform={`translate(${width-14}, ${height-14})`} opacity="0.55">
        <circle cx="4" cy="4" r="3" fill="none" stroke={gold} strokeWidth="0.7" />
        <line x1="4" y1="0" x2="4" y2="1.5" stroke={gold} strokeWidth="0.7" />
        <line x1="4" y1="6.5" x2="4" y2="8" stroke={gold} strokeWidth="0.7" />
        <line x1="0" y1="4" x2="1.5" y2="4" stroke={gold} strokeWidth="0.7" />
        <line x1="6.5" y1="4" x2="8" y2="4" stroke={gold} strokeWidth="0.7" />
      </g>
      {/* Top centre ornament — a small rule with diamond */}
      <line x1={width/2-16} y1="7" x2={width/2-5} y2="7" stroke={gold} strokeWidth="0.5" opacity="0.5" />
      <text x={width/2-3} y="10" style={{fontSize:'5px', fill:gold, opacity:0.6, fontFamily:'Georgia, serif'}}>◆</text>
      <line x1={width/2+2} y1="7" x2={width/2+13} y2="7" stroke={gold} strokeWidth="0.5" opacity="0.5" />
    </svg>
  );
}

// ── Main BookCard — Penguin Great Ideas aesthetic ─────────────────
export function BookCard({ book, status, onClick, selected }) {
  const [hovered, setHovered] = useState(false);
  const id    = book.id || book.title;
  const color = book.color || '#7a5c38';

  // Binding colour — darkened version of book colour, like aged leather
  const binding  = darkenHex(color, 0.30);
  const goldTone = lightenHex(color, 0.60);
  const pct = book.pages ? Math.min(100, Math.round((book.progress / book.pages) * 100)) : 0;

  return (
    <div onClick={onClick}
      onMouseEnter={() => setHovered(true)}
      onMouseLeave={() => setHovered(false)}
      style={{
        width: 120, flexShrink: 0, cursor: 'pointer', position: 'relative',
        transform: hovered ? 'translateY(-6px) rotate(-0.5deg)' : 'translateY(0) rotate(0deg)',
        transition: 'transform 0.2s cubic-bezier(.2,.8,.3,1)',
        filter: selected ? `drop-shadow(0 0 6px ${color}88)` : 'none',
      }}>

      {/* Book body */}
      <div style={{ borderRadius: '2px 3px 3px 2px', overflow: 'hidden', boxShadow: hovered
        ? `3px 8px 20px rgba(0,0,0,0.28), -1px 0 0 rgba(0,0,0,0.15), inset -2px 0 4px rgba(0,0,0,0.08)`
        : `2px 4px 12px rgba(0,0,0,0.20), -1px 0 0 rgba(0,0,0,0.12), inset -2px 0 4px rgba(0,0,0,0.06)`,
        transition: 'box-shadow 0.2s',
      }}>

        {/* ── COVER FACE ── */}
        <div style={{ height: 160, background: binding, position: 'relative', overflow: 'hidden' }}>

          {/* Top strip — Penguin-style colour band with marbling */}
          <div style={{ height: 52, overflow: 'hidden', position: 'relative' }}>
            <MarbledPattern id={id} color={color} width={120} height={52} small />
            {/* Thin gold rule at bottom of band */}
            <div style={{ position:'absolute', bottom:0, left:0, right:0, height:1, background:goldTone, opacity:0.7 }} />
            <div style={{ position:'absolute', bottom:2, left:0, right:0, height:'0.5px', background:goldTone, opacity:0.35 }} />
          </div>

          {/* Title area — the heart of the Penguin aesthetic */}
          <div style={{ padding: '10px 10px 8px', display: 'flex', flexDirection: 'column', gap: 5, position: 'relative', zIndex: 1 }}>
            <div style={{
              fontSize: 11, fontWeight: 700, color: goldTone, lineHeight: 1.25,
              fontFamily: 'var(--font-display)', letterSpacing: '0.01em',
              textShadow: `0 1px 3px rgba(0,0,0,0.4)`,
            }}>
              {book.title}
            </div>
            {/* Thin rule — the Penguin separator */}
            <div style={{ height: '0.75px', background: goldTone, opacity: 0.45 }} />
            <div style={{
              fontSize: 8.5, color: goldTone, opacity: 0.8, fontStyle: 'italic',
              lineHeight: 1.3, fontFamily: 'var(--font-serif)',
            }}>
              {book.author}
            </div>
            {book.year && (
              <div style={{ fontSize: 7, color: goldTone, opacity: 0.5, fontFamily: 'var(--font-mono)', fontStyle: 'normal', letterSpacing: '0.08em', marginTop: 2 }}>
                {book.year < 0 ? `${Math.abs(book.year)} BCE` : book.year}
              </div>
            )}
          </div>

          {/* Ornamental border over everything */}
          <OrnamentalBorder color={goldTone} width={120} height={160} />

          {/* Left spine shadow */}
          <div style={{ position:'absolute', left:0, top:0, bottom:0, width:4, background:'linear-gradient(to right, rgba(0,0,0,0.25), transparent)' }} />

          {/* Reading progress — faint line at bottom */}
          {book.status === 'reading' && book.pages && pct > 0 && (
            <div style={{ position:'absolute', bottom:0, left:0, width:`${pct}%`, height:2, background:goldTone, opacity:0.6 }} />
          )}
        </div>

        {/* Status ribbon */}
        {status && (
          <div style={{ background: darkenHex(color, 0.50), padding: '3px 8px', fontSize: 7, color: goldTone, opacity: 0.85, fontFamily: 'var(--font-mono)', fontStyle: 'normal', letterSpacing: '0.06em', textAlign: 'center' }}>
            {status.label.toUpperCase()}
          </div>
        )}
      </div>
    </div>
  );
}

// ── BookSpine — for shelf view ────────────────────────────────────
export function BookSpine({ book, height = 120, onClick, selected }) {
  const [hovered, setHovered] = useState(false);
  const id      = book.id || book.title;
  const color   = book.color || '#7a5c38';
  const binding = darkenHex(color, 0.30);
  const goldTone = lightenHex(color, 0.60);
  const spineWidth = Math.max(18, Math.min(32, Math.floor(((book.pages || 300) / 800) * 36) + 12));

  return (
    <div onClick={onClick}
      title={`${book.title}${book.author ? ' — ' + book.author : ''}`}
      onMouseEnter={() => setHovered(true)}
      onMouseLeave={() => setHovered(false)}
      style={{
        width: spineWidth, height, flexShrink: 0, cursor: 'pointer', position: 'relative',
        transform: hovered ? 'translateY(-6px)' : 'none',
        transition: 'transform 0.18s cubic-bezier(.2,.8,.3,1)',
      }}>
      <div style={{
        width: '100%', height: '100%', background: binding,
        borderRadius: '2px 3px 3px 2px', overflow: 'hidden', position: 'relative',
        boxShadow: selected
          ? `0 0 0 2px ${color}, 2px 2px 8px rgba(0,0,0,0.3)`
          : hovered
            ? '2px 4px 14px rgba(0,0,0,0.28), -1px 0 0 rgba(0,0,0,0.15)'
            : '1px 2px 6px rgba(0,0,0,0.18), -1px 0 0 rgba(0,0,0,0.1)',
        transition: 'box-shadow 0.18s',
      }}>
        {/* Spine marbling — very thin strip at top */}
        <div style={{ height: 12, overflow: 'hidden' }}>
          <MarbledPattern id={id+'sp'} color={color} width={spineWidth} height={12} small />
        </div>
        {/* Gold rule */}
        <div style={{ height: 1, background: goldTone, opacity: 0.6 }} />
        {/* Title — rotated */}
        <div style={{
          position: 'absolute', top: 16, bottom: 12, left: 0, right: 0,
          display: 'flex', alignItems: 'center', justifyContent: 'center',
        }}>
          <div style={{
            writingMode: 'vertical-rl', textOrientation: 'mixed', transform: 'rotate(180deg)',
            fontSize: 8.5, fontWeight: 600, color: goldTone, letterSpacing: '0.04em',
            padding: '4px 2px', overflow: 'hidden', maxHeight: height - 32,
            textOverflow: 'ellipsis', whiteSpace: 'nowrap', lineHeight: 1.2,
            fontFamily: 'var(--font-display)', textShadow: '0 1px 2px rgba(0,0,0,0.3)',
          }}>
            {book.title}
          </div>
        </div>
        {/* Bottom gold rule */}
        <div style={{ position:'absolute', bottom:10, left:2, right:2, height:'0.75px', background:goldTone, opacity:0.5 }} />
        {/* Left edge shadow */}
        <div style={{ position:'absolute', left:0, top:0, bottom:0, width:3, background:'linear-gradient(to right, rgba(0,0,0,0.22), transparent)' }} />
      </div>
    </div>
  );
}

// ── Endpaper — shown when a book is opened ────────────────────────
export function BookEndpaper({ book, onDone }) {
  const [loading, setLoading] = useState(true);
  const id    = book.id || book.title;
  const color = book.color || '#7a5c38';
  const addr  = '0x' + (book.id || '').slice(0,4).split('').map(c=>c.charCodeAt(0).toString(16)).join('').toUpperCase().padStart(4,'0');

  React.useEffect(() => {
    const t = setTimeout(() => { setLoading(false); if (onDone) onDone(); }, 220);
    return () => clearTimeout(t);
  }, [book.id]);

  return (
    <div style={{ position:'fixed', inset:0, zIndex:9998, display:'flex', alignItems:'center', justifyContent:'center', background:'#000' }}>
      {loading ? (
        <div style={{ textAlign:'center', fontFamily:'DM Mono, monospace' }}>
          <div style={{ fontSize:13, color:'#00ff41', letterSpacing:'0.18em', marginBottom:8 }}>LoAdding...</div>
          <div style={{ fontSize:9, color:'#00ff4188', letterSpacing:'0.12em' }}>[{addr}] · BABEL CONTAINMENT · PAGE TURN</div>
        </div>
      ) : (
        <div style={{ width:360, height:480, position:'relative', boxShadow:'0 20px 60px rgba(0,0,0,0.7)', borderRadius:'2px 4px 4px 2px', overflow:'hidden' }}>
          <MarbledPattern id={id+'end'} color={color} width={360} height={480} />
          <div style={{ position:'absolute', inset:0, display:'flex', alignItems:'center', justifyContent:'center' }}>
            <div style={{ textAlign:'center', padding:'40px 30px' }}>
              <div style={{ fontSize:22, fontFamily:'var(--font-display)', fontWeight:700, fontStyle:'italic', color:darkenHex(color,0.5), marginBottom:12, lineHeight:1.3 }}>{book.title}</div>
              {book.author && <div style={{ fontSize:13, fontStyle:'italic', color:darkenHex(color,0.4) }}>{book.author}</div>}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
